"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8923],{8808(n,e,t){t.r(e),t.d(e,{assets:()=>c,contentTitle:()=>d,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part5-deep-learning-and-llms/cnn-convolution","title":"CNNs \u2014 Part 1: Convolution Mechanics and Intuition","description":"A self-contained, practical introduction to convolution as the core operation behind convolutional neural networks (CNNs). You\u2019ll learn the mechanics (just multiply + add), output sizing, padding modes, and why deep-l...","source":"@site/docs/part5-deep-learning-and-llms/04-cnn-convolution.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/04-cnn-convolution","permalink":"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"CNNs \u2014 Part 1: Convolution Mechanics and Intuition","slug":"/part5-deep-learning-and-llms/04-cnn-convolution","description":"A self-contained, practical introduction to convolution as the core operation behind convolutional neural networks (CNNs). You\u2019ll learn the mechanics (just multiply + add), output sizing, padding modes, and why deep-l...","sidebar_label":"4. CNN convolution","pagination_label":"4. CNN convolution","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"3. FFN single-chapter reference","permalink":"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged"},"next":{"title":"5. CNN architecture","permalink":"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture"}}');var a=t(4848),o=t(8453),l=t(8172);const s=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/04-cnn-convolution.html","route":"/part5-deep-learning-and-llms/04-cnn-convolution","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"CNNs \u2014 Part 1: Convolution","title":"CNNs \u2014 Part 1: Convolution Mechanics and Intuition","description":"A self-contained, practical introduction to convolution as the core operation behind convolutional neural networks (CNNs). You\u2019ll learn the mechanics (just multiply + add), output sizing, padding modes, and why deep-l...","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-convolution-as-an-image-modifier","label":"1) Convolution as an image modifier"},{"id":"2-convolution-mechanics-just-multiply-add","label":"2) Convolution mechanics: just multiply + add"},{"id":"3-output-size-and-convolution-modes-valid-same-full","label":"3) Output size and convolution \u201cmodes\u201d (Valid / Same / Full)"},{"id":"4-pseudocode-and-a-direct-implementation","label":"4) Pseudocode and a direct implementation"},{"id":"5-the-defining-equation-2d","label":"5) The defining equation (2D)"},{"id":"6-convolution-vs-cross-correlation-and-why-deep-learning-uses-the-latter","label":"6) \u201cConvolution\u201d vs cross-correlation (and why deep learning uses the latter)"},{"id":"7-convolution-as-a-sliding-dot-product-similarity-correlation-view","label":"7) Convolution as a sliding dot product (similarity / correlation view)"},{"id":"8-convolution-as-matrix-multiplication-1d-toeplitz-view","label":"8) Convolution as matrix multiplication (1D \u201cToeplitz\u201d view)"},{"id":"9-pytorch-conv2d-quickstart-what-cnn-layers-actually-do","label":"9) PyTorch conv2d quickstart (what CNN layers actually do)"},{"id":"local-visuals-and-source-credits","label":"Local visuals and source credits"}],"html":"<div class=\\"wrap\\">\\n    <header>\\n      \\n      <p>\\n        A self-contained, practical introduction to convolution as the core operation behind convolutional neural networks (CNNs).\\n        You\u2019ll learn the mechanics (just multiply + add), output sizing, padding modes, and why deep-learning \u201cconvolution\u201d is really\\n        <b>cross-correlation</b>. Visuals are served from local assets.\\n      </p>\\n\\n      <div class=\\"chips\\">\\n        <span class=\\"chip\\">Input \u229b Kernel \u2192 Output</span>\\n        <span class=\\"chip\\">Multiply + Add</span>\\n        <span class=\\"chip\\">Valid vs Same vs Full</span>\\n        <span class=\\"chip\\">Cross-correlation vs convolution</span>\\n        <span class=\\"chip\\">Dot product = similarity</span>\\n        <span class=\\"chip\\">Sliding pattern finder</span>\\n      </div>\\n\\n      <nav>\\n        <a href=\\"#intuition\\">Qualitative intuition</a>\\n        <a href=\\"#mechanics\\">Hand-worked example</a>\\n        <a href=\\"#size\\">Output size &amp; modes</a>\\n        <a href=\\"#pseudocode\\">Pseudocode &amp; direct implementation</a>\\n        <a href=\\"#equation\\">Convolution equation</a>\\n        <a href=\\"#corr\\">Cross-correlation vs convolution</a>\\n        <a href=\\"#dot\\">Dot product / cosine similarity view</a>\\n        <a href=\\"#matrix\\">Convolution as matrix multiplication</a>\\n        <a href=\\"#torch\\">PyTorch conv2d quickstart</a>\\n        <a href=\\"#credits\\">Local visuals and credits</a>\\n      </nav>\\n    </header>\\n\\n    <section id=\\"intuition\\">\\n      <h2 id=\\"1-convolution-as-an-image-modifier\\">1) Convolution as an image modifier</h2>\\n      <p>\\n        Convolution takes an <b>input image</b> and a small <b>filter</b> (also called a <b>kernel</b>) and produces an <b>output image</b>.\\n        We write this conceptually as:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\text{output} = \\\\text{input} \\\\;\\\\star\\\\; \\\\text{kernel}\\n        \\\\]\\n      </p>\\n      <p class=\\"muted\\">\\n        In math you often see a star/asterisk for convolution. In code, convolution is not written with <code>*</code> because <code>*</code>\\n        already means multiplication.\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Example A: blurring</b><br>\\n            Using a blur kernel (like Gaussian blur) produces a softened image.\\n          </p>\\n        </div>\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Example B: edge detection</b><br>\\n            Using an edge kernel produces strong responses at boundaries (edges) and low responses elsewhere.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Gaussian blur demonstration\\" src=\\"/tutorials/images/external/Gaussian_blur_effect-27224edd27-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of blur as a convolution effect. Technical reference:\\n          <a href=\\"https://docs.opencv.org/4.x/d4/d13/tutorial_py_filtering.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV image filtering</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <figure>\\n        <img alt=\\"Sobel operator result on an image (edge detection)\\" src=\\"/tutorials/images/external/Sobel_operator_result_on_gray_image-9dc935e09c-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of Sobel edge filtering. Technical reference:\\n          <a href=\\"https://docs.opencv.org/4.x/d2/d2c/tutorial_sobel_derivatives.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV Sobel derivatives</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Why filters matter:</b> the kernel determines what transformation happens. Change the kernel \u2192 you change the effect.\\n          CNNs learn these kernels automatically from data using gradient-based optimization.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"mechanics\\">\\n      <h2 id=\\"2-convolution-mechanics-just-multiply-add\\">2) Convolution mechanics: just multiply + add</h2>\\n\\n      <p>\\n        Convolution \u201cslides\u201d the kernel over the image. At each position, it performs element-wise multiplication\\n        and sums the result. That single number becomes one pixel in the output.\\n      </p>\\n\\n      <h3 id=\\"tiny-worked-example\\">Tiny worked example</h3>\\n      <p class=\\"muted\\">\\n        We\u2019ll use a 4\xd74 input and a 2\xd72 kernel. (Small on purpose so you can verify by hand.)\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div>\\n          <p><b>Input image</b> \\\\(A\\\\)</p>\\n          <table aria-label=\\"Input 4x4 matrix\\">\\n            <tbody><tr><td>0</td><td>10</td><td>10</td><td>0</td></tr>\\n            <tr><td>20</td><td>30</td><td>30</td><td>20</td></tr>\\n            <tr><td>10</td><td>20</td><td>20</td><td>10</td></tr>\\n            <tr><td>0</td><td>5</td><td>5</td><td>0</td></tr>\\n          </tbody></table>\\n        </div>\\n        <div>\\n          <p><b>Kernel</b> \\\\(W\\\\)</p>\\n          <table aria-label=\\"Kernel 2x2 matrix\\">\\n            <tbody><tr><td>1</td><td>0</td></tr>\\n            <tr><td>0</td><td>2</td></tr>\\n          </tbody></table>\\n        </div>\\n      </div>\\n\\n      <p><b>First output (top-left):</b> place the kernel at the top-left 2\xd72 patch of the image:</p>\\n      <p>\\n        \\\\[\\n          1\\\\cdot 0 + 0\\\\cdot 10 + 0\\\\cdot 20 + 2\\\\cdot 30 = 60\\n        \\\\]\\n      </p>\\n\\n      <p><b>Next output (shift right by 1):</b></p>\\n      <p>\\n        \\\\[\\n          1\\\\cdot 10 + 0\\\\cdot 10 + 0\\\\cdot 30 + 2\\\\cdot 30 = 70\\n        \\\\]\\n      </p>\\n\\n      <p><b>Next output (shift right again):</b></p>\\n      <p>\\n        \\\\[\\n          1\\\\cdot 10 + 0\\\\cdot 0 + 0\\\\cdot 30 + 2\\\\cdot 20 = 50\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        Keep sliding until you can\u2019t move right anymore, then move down one row and repeat. The output values stated in the transcript:\\n        \\\\( \\\\begin{bmatrix} 60 &amp; 70 &amp; 50 \\\\\\\\ 60 &amp; 70 &amp; 50 \\\\\\\\ 20 &amp; 30 &amp; 20 \\\\end{bmatrix} \\\\).\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Practice:</b> compute the remaining outputs by hand once. If you can do that, you fully understand the mechanics.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Convolution animation showing a kernel sliding over an image\\" src=\\"/tutorials/images/external/2D_Convolution_Animation-240e665e01.gif\\">\\n        <figcaption>\\n          Sliding-window convolution visualization (Wikimedia Commons):\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:2D_Convolution_Animation.gif\\" target=\\"_blank\\" rel=\\"noopener\\">2D_Convolution_Animation.gif</a>\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"size\\">\\n      <h2 id=\\"3-output-size-and-convolution-modes-valid-same-full\\">3) Output size and convolution \u201cmodes\u201d (Valid / Same / Full)</h2>\\n\\n      <p>\\n        If the input has height \\\\(H\\\\), width \\\\(W\\\\), and the kernel has height \\\\(K_H\\\\), width \\\\(K_W\\\\),\\n        then with <b>no padding</b> and stride 1, the output size is:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          H_{\\\\text{out}} = H - K_H + 1,\\\\quad W_{\\\\text{out}} = W - K_W + 1\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        This is the \u201cvalid\u201d mode: you only place the kernel where it fully fits inside the input.\\n      </p>\\n\\n      <h3 id=\\"padding-making-output-the-same-size\\">Padding: making output the same size</h3>\\n      <p>\\n        If you pad the input with zeros around the border, you allow the kernel to slide beyond the original edges.\\n        With padding \\\\(P_H, P_W\\\\) and stride 1:\\n      </p>\\n      <p>\\n        \\\\[\\n          H_{\\\\text{out}} = H + 2P_H - K_H + 1,\\\\quad W_{\\\\text{out}} = W + 2P_W - K_W + 1\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        To get <b>same</b> output size (i.e., \\\\(H_{\\\\text{out}}=H\\\\), \\\\(W_{\\\\text{out}}=W\\\\)) with odd square kernels\\n        (like \\\\(3\\\\times 3\\\\), \\\\(5\\\\times 5\\\\)), choose:\\n      </p>\\n      <p>\\n        \\\\[\\n          P = \\\\frac{K-1}{2}\\n        \\\\]\\n      </p>\\n\\n      <h3 id=\\"full-mode-catch-everything\\">Full mode: \u201ccatch everything\u201d</h3>\\n      <p class=\\"muted\\">\\n        If you keep padding so the kernel can slide over every partial overlap, the 1D output length becomes:\\n        \\\\[\\n          n_{\\\\text{out}} = n + k - 1\\n        \\\\]\\n        (and similarly in 2D). This is the classic \u201cfull\u201d convolution size.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Convolution padding illustration\\" src=\\"/tutorials/images/external/Convolution_arithmetic_padding_strides-939a950445-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of padding and stride arithmetic. Technical reference:\\n          <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">\\n            Dumoulin and Visin, <em>A guide to convolution arithmetic for deep learning</em>\\n          </a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Practical note:</b> images \u201cin the wild\u201d are often rectangular, but kernels are usually square by convention\\n          (e.g., 3\xd73, 5\xd75).\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"pseudocode\\">\\n      <h2 id=\\"4-pseudocode-and-a-direct-implementation\\">4) Pseudocode and a direct implementation</h2>\\n\\n      <p>\\n        A straightforward 2D convolution (valid, stride 1) can be written with four loops:\\n        two for output position \\\\((i,j)\\\\) and two for kernel position \\\\((i\',j\')\\\\).\\n      </p>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 naive 2D \u201cdeep learning style\u201d convolution (cross-correlation), valid mode</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import numpy as np\\n\\ndef corr2d_valid(A, W):\\n    \\"\\"\\"\\n    Cross-correlation (deep-learning \'convolution\') in 2D, valid mode, stride=1.\\n    A: (H, W) input\\n    W: (Kh, Kw) kernel\\n    returns: (H-Kh+1, W-Kw+1)\\n    \\"\\"\\"\\n    H, W_in = A.shape\\n    Kh, Kw = W.shape\\n    H_out = H - Kh + 1\\n    W_out = W_in - Kw + 1\\n    out = np.zeros((H_out, W_out), dtype=float)\\n\\n    for i in range(H_out):\\n        for j in range(W_out):\\n            s = 0.0\\n            for ii in range(Kh):\\n                for jj in range(Kw):\\n                    s += A[i + ii, j + jj] * W[ii, jj]\\n            out[i, j] = s\\n    return out\\n\\nA = np.array([[0,10,10,0],\\n              [20,30,30,20],\\n              [10,20,20,10],\\n              [0, 5, 5, 0]], dtype=float)\\n\\nW = np.array([[1,0],\\n              [0,2]], dtype=float)\\n\\nprint(corr2d_valid(A, W))</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        This code matches the lecture\u2019s \u201cmultiply + add\u201d definition and produces the 3\xd73 output for the 4\xd74 input with a 2\xd72 kernel.\\n      </p>\\n    </section>\\n\\n    <section id=\\"equation\\">\\n      <h2 id=\\"5-the-defining-equation-2d\\">5) The defining equation (2D)</h2>\\n\\n      <p>\\n        The 2D deep-learning version (cross-correlation) at output location \\\\((i,j)\\\\) is:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          (A \\\\star W)_{i,j} = \\\\sum_{i\'=0}^{K_H-1}\\\\sum_{j\'=0}^{K_W-1} A_{i+i\',\\\\, j+j\'} \\\\, W_{i\',\\\\, j\'}\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        This equation is exactly what the nested loops compute.\\n      </p>\\n    </section>\\n\\n    <section id=\\"corr\\">\\n      <h2 id=\\"6-convolution-vs-cross-correlation-and-why-deep-learning-uses-the-latter\\">6) \u201cConvolution\u201d vs cross-correlation (and why deep learning uses the latter)</h2>\\n\\n      <p>\\n        In classic signal processing, convolution flips the kernel (reverses its orientation). In deep learning libraries,\\n        the operation called \u201cconvolution\u201d typically does <b>not</b> flip the kernel.\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Cross-correlation (deep learning style):</b><br>\\n            slide the kernel as-is\\n          </p>\\n        </div>\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Convolution (signal processing):</b><br>\\n            slide a flipped kernel\\n          </p>\\n        </div>\\n      </div>\\n\\n      <p>\\n        If the kernel is learned automatically (as in CNN training), the flip convention doesn\u2019t change what the model can learn:\\n        the optimizer can learn flipped patterns just as easily.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Cross-correlation illustration\\" src=\\"/tutorials/images/external/Cross-correlation_animation-2697dc7269-fallback.svg\\">\\n        <figcaption>\\n          Local book visualization of cross-correlation. API reference:\\n          <a href=\\"https://docs.pytorch.org/docs/stable/generated/torch.nn.Conv2d.html\\" target=\\"_blank\\" rel=\\"noopener\\">PyTorch <code>Conv2d</code></a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Takeaway:</b> it\u2019s helpful to think of CNN kernels as <b>patterns</b> and the operation as a sliding\\n          <b>pattern matcher</b>.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"dot\\">\\n      <h2 id=\\"7-convolution-as-a-sliding-dot-product-similarity-correlation-view\\">7) Convolution as a sliding dot product (similarity / correlation view)</h2>\\n\\n      <p>\\n        A dot product between vectors \\\\(a\\\\) and \\\\(b\\\\) can be written in two equivalent ways:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          a \\\\cdot b = \\\\sum_{i=1}^d a_i b_i\\n        \\\\]\\n      </p>\\n      <p>\\n        \\\\[\\n          a \\\\cdot b = \\\\|a\\\\| \\\\, \\\\|b\\\\| \\\\cos(\\\\theta)\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        The cosine term \\\\(\\\\cos(\\\\theta)\\\\) is a similarity measure:\\n      </p>\\n      <ul>\\n        <li>\\\\(\\\\theta=0^\\\\circ \\\\Rightarrow \\\\cos(\\\\theta)=1\\\\) (most similar)</li>\\n        <li>\\\\(\\\\theta=90^\\\\circ \\\\Rightarrow \\\\cos(\\\\theta)=0\\\\) (orthogonal / unrelated)</li>\\n        <li>\\\\(\\\\theta=180^\\\\circ \\\\Rightarrow \\\\cos(\\\\theta)=-1\\\\) (opposite)</li>\\n      </ul>\\n\\n      <figure>\\n        <img alt=\\"Dot product geometric interpretation\\" src=\\"/tutorials/images/external/Dot_Product-33b408b592-fallback.svg\\">\\n        <figcaption>\\n          Geometric view of dot product (Wikimedia Commons):\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Dot_Product.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Dot_Product.svg</a>\\n        </figcaption>\\n      </figure>\\n\\n      <p>\\n        Convolution/correlation is essentially the same dot-product idea, but repeated over all image locations:\\n      </p>\\n      <ol>\\n        <li>take a local patch of the image (same shape as kernel)</li>\\n        <li>compute dot product with the kernel</li>\\n        <li>store result in output at that location</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Pattern-finder interpretation:</b> the kernel encodes a pattern.\\n          Sliding it across the image asks: \u201chow similar is this patch to my pattern?\u201d High response \u2192 pattern present.\\n        </p>\\n      </div>\\n\\n      <h3 id=\\"cosine-similarity-vs-pearson-correlation-conceptual-link\\">Cosine similarity vs Pearson correlation (conceptual link)</h3>\\n      <p class=\\"muted\\">\\n        Pearson correlation looks like cosine similarity but with mean subtraction. That\u2019s another reason the word \u201ccorrelation\u201d\\n        is a helpful mental model for what CNN filters do.\\n      </p>\\n    </section>\\n\\n    <section id=\\"matrix\\">\\n      <h2 id=\\"8-convolution-as-matrix-multiplication-1d-toeplitz-view\\">8) Convolution as matrix multiplication (1D \u201cToeplitz\u201d view)</h2>\\n\\n      <p>\\n        In 1D, a length-\\\\(n\\\\) input \\\\(a=[a_1,a_2,\\\\dots,a_n]\\\\) convolved (in deep-learning style) with a length-\\\\(k\\\\) kernel\\n        \\\\(w=[w_1,\\\\dots,w_k]\\\\) produces:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          b_i = \\\\sum_{i\'=1}^{k} a_{i+i\'-1}\\\\, w_{i\'} \\\\quad \\\\text{for } i=1,\\\\dots,n-k+1\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        You can implement the same operation by building a matrix that repeats and shifts the kernel across rows\\n        (a Toeplitz-like matrix), then multiplying by the input vector. This shows convolution is a <b>linear operation</b>.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Why we don\u2019t do this in practice:</b> the equivalent matrix is huge because it repeats kernel parameters many times.\\n          CNNs avoid this by storing the small kernel once and reusing it everywhere (parameter sharing).\\n        </p>\\n      </div>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 1D convolution via explicit matrix multiplication (teaching only)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import numpy as np\\n\\ndef conv1d_via_matrix(a, w):\\n    a = np.asarray(a, dtype=float)\\n    w = np.asarray(w, dtype=float)\\n    n = a.size\\n    k = w.size\\n    out_len = n - k + 1\\n\\n    # Build \\"convolution matrix\\" M of shape (out_len, n)\\n    M = np.zeros((out_len, n), dtype=float)\\n    for i in range(out_len):\\n        M[i, i:i+k] = w  # place kernel in row i, shifted right by i\\n\\n    b = M @ a\\n    return b, M\\n\\na = [1, 2, 3, 4]\\nw = [10, 100]\\nb, M = conv1d_via_matrix(a, w)\\n\\nprint(\\"M=\\\\n\\", M)\\nprint(\\"b=\\", b)</code></pre>\\n      </div>\\n    </section>\\n\\n    <section id=\\"torch\\">\\n      <h2 id=\\"9-pytorch-conv2d-quickstart-what-cnn-layers-actually-do\\">9) PyTorch conv2d quickstart (what CNN layers actually do)</h2>\\n\\n      <p>\\n        A CNN layer applies many kernels to an input. In PyTorch:\\n      </p>\\n      <ul>\\n        <li>input tensor shape: \\\\((N, C_{\\\\text{in}}, H, W)\\\\)</li>\\n        <li>output tensor shape: \\\\((N, C_{\\\\text{out}}, H_{\\\\text{out}}, W_{\\\\text{out}})\\\\)</li>\\n        <li>weights shape: \\\\((C_{\\\\text{out}}, C_{\\\\text{in}}, K_H, K_W)\\\\)</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Important:</b> this is still \u201cmultiply + add\u201d, just extended across channels and many filters.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Conv layer with multiple channels illustration\\" src=\\"/tutorials/images/external/Typical_cnn-46df08c8b8-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of a multi-channel CNN. Historical reference:\\n          <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 minimal conv2d example (demonstrates shapes, padding, valid vs same-like)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\n# N=1 image, Cin=1 channel, H=W=4\\nx = torch.tensor([[[[0., 10., 10., 0.],\\n                    [20., 30., 30., 20.],\\n                    [10., 20., 20., 10.],\\n                    [0.,  5.,  5.,  0.]]]])\\n\\n# One output channel, one input channel, kernel 2x2\\nconv = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=2, bias=False)\\n\\n# Manually set weights to match the earlier kernel [[1,0],[0,2]]\\nwith torch.no_grad():\\n    conv.weight[:] = torch.tensor([[[[1., 0.],\\n                                     [0., 2.]]]])\\n\\ny_valid = conv(x)              # padding=0 by default -&gt; \\"valid\\"\\nprint(\\"valid out shape:\\", y_valid.shape)\\nprint(y_valid[0,0])\\n\\n# If you want \\"same\\" output size, you typically pad (for odd kernels).\\n# Here kernel is 2x2; \\"same\\" is less symmetric. We\'ll show padding=1 anyway:\\nconv_pad = nn.Conv2d(1, 1, kernel_size=2, padding=1, bias=False)\\nwith torch.no_grad():\\n    conv_pad.weight[:] = conv.weight\\n\\ny_padded = conv_pad(x)\\nprint(\\"padded out shape:\\", y_padded.shape)\\nprint(y_padded[0,0])</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        This example uses PyTorch\u2019s deep-learning \u201cconvolution\u201d (cross-correlation). The values match the hand computation for valid mode.\\n      </p>\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Terminology precision:</b> classical signal-processing convolution flips the kernel before sliding it.\\n          Most deep-learning libraries, including PyTorch <code>Conv2d</code>, compute cross-correlation instead.\\n          Because kernels are learned, the distinction usually does not change model expressiveness, but it matters when\\n          you manually compare against a textbook convolution formula.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"credits\\">\\n      <h2 id=\\"local-visuals-and-source-credits\\">Local visuals and source credits</h2>\\n      <ul class=\\"small\\">\\n        <li>Gaussian blur diagram: local book asset; concept reference: <a href=\\"https://docs.opencv.org/4.x/d4/d13/tutorial_py_filtering.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV image filtering</a></li>\\n        <li>Sobel edge diagram: local book asset; concept reference: <a href=\\"https://docs.opencv.org/4.x/d2/d2c/tutorial_sobel_derivatives.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV Sobel derivatives</a></li>\\n        <li>2D convolution animation: <a href=\\"https://commons.wikimedia.org/wiki/File:2D_Convolution_Animation.gif\\" target=\\"_blank\\" rel=\\"noopener\\">2D_Convolution_Animation.gif</a></li>\\n        <li>Padding/stride arithmetic: local book asset; concept reference: <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a></li>\\n        <li>Cross-correlation diagram: local book asset; API reference: <a href=\\"https://docs.pytorch.org/docs/stable/generated/torch.nn.Conv2d.html\\" target=\\"_blank\\" rel=\\"noopener\\">PyTorch <code>Conv2d</code></a></li>\\n        <li>Dot product geometry: <a href=\\"https://commons.wikimedia.org/wiki/File:Dot_Product.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Dot_Product.svg</a></li>\\n        <li>CNN diagram: local book asset; historical reference: <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a></li>\\n      </ul>\\n\\n      <div class=\\"hr\\"></div>\\n      <p class=\\"muted small\\">\\n        This HTML is designed to be self-sufficient: equations render via MathJax, code blocks use the shared book copy controls,\\n        and plots/animations are served from local assets.\\n      </p>\\n    </section>\\n\\n  </div>"}'),r={title:"CNNs \u2014 Part 1: Convolution Mechanics and Intuition",slug:"/part5-deep-learning-and-llms/04-cnn-convolution",description:"A self-contained, practical introduction to convolution as the core operation behind convolutional neural networks (CNNs). You\u2019ll learn the mechanics (just multiply + add), output sizing, padding modes, and why deep-l...",sidebar_label:"4. CNN convolution",pagination_label:"4. CNN convolution",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function u(n){return(0,a.jsx)(l.A,{content:s})}function h(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,a.jsx)(e,{...n,children:(0,a.jsx)(u,{...n})}):u()}}}]);